const {chromium}=require('playwright');(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:768,height:900}});await p.goto('file://'+process.cwd()+'/comb3/03-document-library.html');await p.waitForTimeout(300);const s=await p.$$('.fig-state');const bb=await s[1].boundingBox();await p.screenshot({path:'c03m.png',clip:{x:0,y:bb.y,width:390,height:1500},fullPage:true});await b.close()})();
